/**
 * Cross-language contract test: decodes binary fixtures emitted by Go's
 * `transport.BinaryCodec` and asserts the TS BinaryCodec matches.
 *
 * Fixtures are generated by `go test -run TestBinaryCodec_EmitFixtures -v
 * ./transport/...` in the spore repository. If the wire format changes,
 * re-run that test and copy the new hex strings here.
 */

import { describe, expect, it } from "vitest";
import { BinaryCodec } from "../src/binary_codec.js";
import type { ObjectDesc, TypeDesc } from "../src/schema.js";

function fromHex(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(hex.substring(i * 2, i * 2 + 2), 16);
  }
  return out;
}

// ---------------------------------------------------------------------------
// Fixtures (verbatim hex from Go BinaryCodec emitter)
// ---------------------------------------------------------------------------

const FX = {
  bool_true: "5442430302",
  bool_false: "5442430301",
  int32_42: "54424303030000002a",
  int32_neg: "5442430303fffffff9",
  int64_small: "544243030400000000075bcd15",
  string_hello: "54424303070568656c6c6f",
  string_utf8: "54424303070d68c3a96c6c6f20e4b896e7958c",
  bytes_deadbeef: "544243030804deadbeef",
  float_pi: "5442430306400921f9f01b866e",
  array_strings: "544243030903070161070162070163",
  map_three: "544243030a0301610300000002016d0300000003017a0300000001",
  ordered_map_zam: "544243030b0307017a030000001a070161030000000107016d030000000d",
  struct_voice_audio: "544243030cbf030200030000000201080401020304",
  struct_voice_recognize_req: "544243030cbe0301000c000209417564696f54797065030000000204446174610806deadbeef00ff",
} as const;

const codec = new BinaryCodec();

function toHex(b: Uint8Array): string {
  return Array.from(b)
    .map((x) => x.toString(16).padStart(2, "0"))
    .join("");
}

describe("BinaryCodec cross-language contract (decode Go fixtures)", () => {
  it("bool true", () => {
    expect(codec.decode({ kind: "scalar", name: "bool" }, fromHex(FX.bool_true))).toBe(true);
  });

  it("bool false", () => {
    expect(codec.decode({ kind: "scalar", name: "bool" }, fromHex(FX.bool_false))).toBe(false);
  });

  it("int32 positive", () => {
    expect(codec.decode({ kind: "scalar", name: "int32" }, fromHex(FX.int32_42))).toBe(42);
  });

  it("int32 negative", () => {
    expect(codec.decode({ kind: "scalar", name: "int32" }, fromHex(FX.int32_neg))).toBe(-7);
  });

  it("int64 (Go 'int' schema) decodes to number when safe", () => {
    const v = codec.decode({ kind: "scalar", name: "int64" }, fromHex(FX.int64_small));
    expect(v).toBe(123456789);
  });

  it("string ascii", () => {
    expect(codec.decode({ kind: "scalar", name: "string" }, fromHex(FX.string_hello))).toBe("hello");
  });

  it("string utf-8", () => {
    expect(codec.decode({ kind: "scalar", name: "string" }, fromHex(FX.string_utf8))).toBe("héllo 世界");
  });

  it("bytes", () => {
    const out = codec.decode({ kind: "scalar", name: "bytes" }, fromHex(FX.bytes_deadbeef)) as Uint8Array;
    expect(out).toBeInstanceOf(Uint8Array);
    expect(Array.from(out)).toEqual([0xde, 0xad, 0xbe, 0xef]);
  });

  it("float64 pi", () => {
    expect(codec.decode({ kind: "scalar", name: "float64" }, fromHex(FX.float_pi))).toBeCloseTo(3.14159, 10);
  });

  it("array of strings", () => {
    const desc: TypeDesc = { kind: "array", element: { kind: "scalar", name: "string" } };
    expect(codec.decode(desc, fromHex(FX.array_strings))).toEqual(["a", "b", "c"]);
  });

  it("plain map (alphabetical wire order)", () => {
    const desc: TypeDesc = {
      kind: "map",
      key: { kind: "scalar", name: "string" },
      value: { kind: "scalar", name: "int32" },
    };
    const out = codec.decode(desc, fromHex(FX.map_three)) as Record<string, number>;
    expect(out).toEqual({ a: 2, m: 3, z: 1 });
  });

  it("OrderedMap as entry sequence (insertion order preserved)", () => {
    const desc: TypeDesc = {
      kind: "map",
      key: { kind: "scalar", name: "string" },
      value: { kind: "scalar", name: "int32" },
    };
    const entries = codec.decode(desc, fromHex(FX.ordered_map_zam)) as Array<{ Key: string; Value: number }>;
    expect(entries.map((e) => e.Key)).toEqual(["z", "a", "m"]);
    expect(entries.map((e) => e.Value)).toEqual([26, 1, 13]);
  });
});

// ---------------------------------------------------------------------------
// Re-encode check: bytes the TS codec produces match Go's bytes verbatim.
// ---------------------------------------------------------------------------

describe("BinaryCodec cross-language contract (TS encode matches Go bytes)", () => {
  it("bool true", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "bool" }, true))).toBe(FX.bool_true);
  });

  it("bool false", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "bool" }, false))).toBe(FX.bool_false);
  });

  it("int32 positive", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "int32" }, 42))).toBe(FX.int32_42);
  });

  it("int32 negative", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "int32" }, -7))).toBe(FX.int32_neg);
  });

  it("string ascii", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "string" }, "hello"))).toBe(FX.string_hello);
  });

  it("string utf-8", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "string" }, "héllo 世界"))).toBe(FX.string_utf8);
  });

  it("bytes", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "bytes" }, new Uint8Array([0xde, 0xad, 0xbe, 0xef])))).toBe(
      FX.bytes_deadbeef,
    );
  });

  it("float64 pi", () => {
    expect(toHex(codec.encode({ kind: "scalar", name: "float64" }, 3.14159))).toBe(FX.float_pi);
  });

  it("array of strings", () => {
    const desc: TypeDesc = { kind: "array", element: { kind: "scalar", name: "string" } };
    expect(toHex(codec.encode(desc, ["a", "b", "c"]))).toBe(FX.array_strings);
  });

  it("plain map (alphabetical)", () => {
    const desc: TypeDesc = {
      kind: "map",
      key: { kind: "scalar", name: "string" },
      value: { kind: "scalar", name: "int32" },
    };
    expect(toHex(codec.encode(desc, { z: 1, a: 2, m: 3 }))).toBe(FX.map_three);
  });

  it("OrderedMap as entry sequence preserves insertion order", () => {
    const desc: TypeDesc = {
      kind: "map",
      key: { kind: "scalar", name: "string" },
      value: { kind: "scalar", name: "int32" },
    };
    const entries = [
      { Key: "z", Value: 26 },
      { Key: "a", Value: 1 },
      { Key: "m", Value: 13 },
    ];
    expect(toHex(codec.encode(desc, entries))).toBe(FX.ordered_map_zam);
  });
});

// ---------------------------------------------------------------------------
// Struct cross-language: Go encodes struct as TAG_STRUCT with schema ID and
// field-index encoding. Nested structs use classID=0 (anonymous) with string
// keys since Go reflection doesn't carry field-level schema info.
// TS mirrors the same encoding with objectFor providing ObjectDesc.
// ---------------------------------------------------------------------------

const voiceAudioObj: ObjectDesc = {
  kind: "struct",
  name: "VoiceAudio",
  fields: [
    { name: "AudioType", type: { kind: "scalar", name: "int32", typeId: 6 } },
    { name: "Data", type: { kind: "scalar", name: "bytes", typeId: 13 } },
  ],
};
const voiceReqObj: ObjectDesc = {
  kind: "struct",
  name: "VoiceRecognizeReq",
  fields: [
    { name: "Audio", type: { kind: "struct", name: "VoiceAudio", className: "VoiceAudio" } },
  ],
};

const objectFor = (name: string): ObjectDesc | undefined => {
  if (name === "VoiceAudio") return voiceAudioObj;
  if (name === "VoiceRecognizeReq") return voiceReqObj;
  return undefined;
};

describe("BinaryCodec cross-language contract (struct with bytes)", () => {
  it("decodes Go-encoded flat struct (VoiceAudio)", () => {
    const desc: TypeDesc = { kind: "struct", name: "VoiceAudio", className: "VoiceAudio", classId: 447 };
    const out = codec.decode(desc, fromHex(FX.struct_voice_audio), objectFor) as Record<string, unknown>;
    expect(out.AudioType).toBe(2);
    expect(Array.from(out.Data as Uint8Array)).toEqual([0x01, 0x02, 0x03, 0x04]);
  });

  it("decodes Go-encoded nested struct (VoiceRecognizeReq)", () => {
    const desc: TypeDesc = { kind: "struct", name: "VoiceRecognizeReq", className: "VoiceRecognizeReq", classId: 446 };
    const out = codec.decode(desc, fromHex(FX.struct_voice_recognize_req), objectFor) as Record<string, unknown>;
    const audio = out.Audio as Record<string, unknown>;
    expect(audio.AudioType).toBe(2);
    expect(Array.from(audio.Data as Uint8Array)).toEqual([0xde, 0xad, 0xbe, 0xef, 0x00, 0xff]);
  });

  it("TS encodes flat struct matching Go bytes", () => {
    const desc: TypeDesc = { kind: "struct", name: "VoiceAudio", className: "VoiceAudio", classId: 447 };
    const out = codec.encode(desc, { AudioType: 2, Data: new Uint8Array([0x01, 0x02, 0x03, 0x04]) }, objectFor);
    expect(toHex(out)).toBe(FX.struct_voice_audio);
  });

  it("TS encodes nested struct matching Go bytes", () => {
    const desc: TypeDesc = { kind: "struct", name: "VoiceRecognizeReq", className: "VoiceRecognizeReq", classId: 446 };
    const out = codec.encode(desc, {
      Audio: { AudioType: 2, Data: new Uint8Array([0xde, 0xad, 0xbe, 0xef, 0x00, 0xff]) },
    }, objectFor);
    expect(toHex(out)).toBe(FX.struct_voice_recognize_req);
  });
});
